-- GlowUp | V24: descrições comerciais dos 50 produtos do catálogo inicial.
-- Só preenche produtos que ainda NÃO têm descrição (descricao nula ou vazia): nunca sobrescreve texto
-- que a Domingas tenha escrito pelo painel. Para ajustar um texto depois, edite o produto no painel.
-- Os textos descrevem perfil e uso de forma geral; confira volume, notas e indicações na embalagem de cada item.

UPDATE produtos AS p
SET descricao = d.descricao
FROM (
    VALUES
    ('Creme Acetinado Hidratante Desodorante Corporal Lily 250g', 'Creme acetinado de textura macia que hidrata a pele e deixa um toque sedoso, com o perfume floral e luminoso da linha Lily. Absorve com facilidade, sem sensação pegajosa, e mantém o corpo perfumado por mais tempo. Ideal para usar depois do banho em braços, pernas e colo. Combina com o Body Splash e o Desodorante Lily para uma rotina completa. Pote de 250g.'),
    ('Body Splash Desodorante Colônia Lily 200ml', 'Body Splash com a fragrância floral e feminina da linha Lily em versão leve e refrescante. Borrife no corpo depois do banho ou ao longo do dia para renovar o perfume e a sensação de frescor. Prático para levar na bolsa, na academia ou para o fim do expediente. Combina com o creme hidratante e o desodorante da mesma linha. Frasco de 200ml.'),
    ('Desodorante Antitranspirante Aerossol Lily 75g/125ml', 'Desodorante antitranspirante em aerossol com a assinatura floral do Lily. Oferece proteção contra o suor e o odor, secagem rápida e um perfume agradável que acompanha a rotina. Aplique a cerca de 15 cm da pele limpa e seca e mantenha longe do fogo. Prático, ideal para o dia a dia e para levar na bolsa. Versão 75g/125ml.'),
    ('Malbec Desodorante Colônia 100ml', 'Colônia masculina clássica de personalidade marcante, com perfil amadeirado e aromático que transmite elegância e confiança. Uma das fragrâncias masculinas mais queridas do catálogo, ótima para o trabalho, encontros e ocasiões especiais. Fragrância de presença, pensada para durar ao longo do dia. Frasco de 100ml.'),
    ('Arbo Desodorante Colônia 100ml', 'Desodorante colônia masculino com perfil fresco e amadeirado, que remete à força e à frescura da natureza. Uma fragrância moderna e versátil, que funciona do trabalho ao fim de semana. Aplique após o banho, em pulsos e pescoço, para um perfume marcante sem exageros. Frasco de 100ml.'),
    ('Accordes Desodorante Colônia 80ml', 'Fragrância masculina sofisticada, construída em uma harmonia de notas amadeiradas e aromáticas. Passa a imagem de um homem elegante, seguro e atento aos detalhes. Excelente opção para presentear ou para ter como perfume de assinatura. Desodorante colônia em frasco de 80ml.'),
    ('Floratta Rose Desodorante Colônia 75ml', 'Floral delicada e romântica, com a suavidade da rosa como destaque. Uma fragrância feminina leve e envolvente, perfeita para o dia a dia e para momentos especiais. Aplique após o banho, em pulsos e colo, e reaplique quando quiser renovar o perfume. Desodorante colônia em frasco de 75ml.'),
    ('Her Code Eau de Parfum 50ml', 'Eau de Parfum feminino, de alta concentração, que traz mais presença e fixação do que uma colônia tradicional. Uma fragrância sensual e marcante para quem quer deixar a sua assinatura por onde passa. Ótima para noites, encontros e ocasiões especiais, e também um presente que impressiona. Frasco de 50ml.'),
    ('Floratta Red Desodorante Colônia 75ml', 'Fragrância floral intensa e sensual, com personalidade para quem gosta de perfume que se faz notar. Feminina, marcante e perfeita para a noite, encontros e ocasiões especiais. Aplique em pulsos, pescoço e colo para um efeito envolvente. Desodorante colônia em frasco de 75ml.'),
    ('Egeo Original Desodorante Colônia 90ml', 'Fragrância jovem, fresca e descontraída, feita para o dia a dia. Leve e fácil de usar, é aquela que combina com qualquer ocasião, do trabalho ao passeio. Uma clássica do catálogo, ótima para quem prefere um perfume agradável e sem exageros. Desodorante colônia em frasco de 90ml.'),
    ('Egeo Dolce Desodorante Colônia 90ml', 'Versão doce e envolvente da linha Egeo, com um toque gourmand que aconchega e deixa um rastro agradável. Perfeita para quem gosta de fragrâncias cheirosas e reconfortantes, para usar no dia a dia ou à noite. Desodorante colônia em frasco de 90ml.'),
    ('Coffee Woman Desodorante Colônia 100ml', 'Inspirada no universo do café, esta fragrância feminina é aconchegante, sedutora e cheia de personalidade, com um toque gourmand inconfundível. Ótima para quem gosta de perfumes diferentes e marcantes, para o dia ou para a noite. Desodorante colônia em frasco de 100ml.'),
    ('Body Splash Desodorante Colônia L''eau de Lily 200ml', 'Body Splash em versão leve e refrescante da família Lily, com perfume floral suave e feminino. Borrife depois do banho ou durante o dia para renovar o frescor. Prático para a bolsa e ótimo para dias quentes. Frasco de 200ml.'),
    ('Liz Desodorante Colônia 100ml', 'Fragrância feminina delicada, com perfil suave que acompanha bem o dia a dia. Um perfume leve e agradável, sem pesar, para quem gosta de cheirinho discreto e elegante. Aplique depois do banho e reaplique sempre que quiser. Desodorante colônia em frasco de 100ml.'),
    ('Creme Desodorante Hidratante Corporal Liz 250g', 'Creme hidratante corporal com a fragrância da linha Liz, para cuidar da pele no dia a dia. Textura confortável, que hidrata, deixa a pele macia e perfumada e é fácil de espalhar. Use depois do banho em todo o corpo. Combina com a colônia Liz para prolongar o perfume. Pote de 250g.'),
    ('Creme Acetinado Hidratante Desodorante Corporal Elysée 250g', 'Creme acetinado hidratante com a fragrância Elysée, de textura macia que deixa a pele com toque sedoso e perfumada. Aplique depois do banho, massageando até a completa absorção, para um cuidado diário com sensação de luxo. Pote de 250g.'),
    ('Linda Desodorante Colônia 100ml', 'Fragrância feminina alegre e vibrante, com perfil floral e frutado que transmite leveza e bom humor. Perfeita para o dia a dia, para quem gosta de um perfume cheiroso e marcante sem ser pesado. Desodorante colônia em frasco de 100ml.'),
    ('Óleo Desodorante Corporal Nativa SPA Ameixa 200ml', 'Óleo corporal desodorante com a fragrância envolvente de ameixa da linha Nativa SPA. Aplique sobre a pele ainda úmida, depois do banho, para hidratar, deixar a pele macia com brilho acetinado e perfumada por mais tempo. Um ritual de spa para fazer em casa. Frasco de 200ml.'),
    ('Zaad Eau de Parfum 95ml', 'Eau de Parfum masculino de alta concentração, com presença forte e sofisticada. Uma fragrância para o homem que gosta de ser notado e de um perfume que dura. Perfeita para noites, eventos e ocasiões especiais, e um presente de impacto. Frasco de 95ml.'),
    ('Glamour Desodorante Colônia 75ml', 'Fragrância feminina elegante e glamourosa, pensada para quem gosta de brilhar. Um perfume com presença, ótimo para festas, encontros e ocasiões especiais. Aplique em pulsos, pescoço e colo para um efeito sofisticado. Desodorante colônia em frasco de 75ml.'),
    ('Quasar Classic Desodorante Colônia 100ml', 'Fragrância masculina fresca e energética, de perfil clássico. Passa uma imagem de confiança e é versátil o bastante para o trabalho, o dia a dia e o fim de semana. Um perfume fácil de gostar e de presentear. Desodorante colônia em frasco de 100ml.'),
    ('Boticollection Portinari Desodorante Colônia 100ml', 'Fragrância da linha Boticollection, uma coleção que traz identidade e personalidade para quem aprecia perfumes diferenciados. Uma opção para quem busca um cheiro marcante e exclusivo e gosta de ter algo especial na penteadeira. Desodorante colônia em frasco de 100ml.'),
    ('Desodorante Colônia Kaiak Masculino 100ml', 'Colônia masculina da linha Kaiak, famosa pela energia e pela frescura. Um perfume aquático e vibrante, pensado para o homem ativo e cheio de energia, ótimo para o calor e o dia a dia. Aplique depois do banho e sinta o frescor durante o dia. Frasco de 100ml.'),
    ('Desodorante Body Spray Kaiak Masculino 100ml', 'Body Spray da linha Kaiak masculino, com a frescura e a energia que marcam a linha. Prático, de aplicação rápida, é perfeito para academia, trabalho e aqueles dias em que você precisa renovar o perfume. Frasco de 100ml.'),
    ('Desodorante Colônia Kaiak Feminino 100ml', 'Colônia feminina da linha Kaiak, com perfume fresco e vibrante que traz leveza e energia. Ótima para dias quentes e para quem gosta de uma fragrância jovem e cheia de vida. Aplique depois do banho e reaplique sempre que quiser. Frasco de 100ml.'),
    ('Desodorante Body Spray Kaiak Feminino 100ml', 'Body Spray da linha Kaiak feminino, com a frescura e a leveza que marcam a linha. Prático e rápido, é ótimo para levar na bolsa e renovar o perfume ao longo do dia, no trabalho, na academia ou no passeio. Frasco de 100ml.'),
    ('Desodorante Colônia Luna Feminino 75ml', 'Fragrância feminina luminosa e envolvente, que valoriza quem a usa. Um perfume cheio de presença e delicadeza, ótimo para o dia a dia e para ocasiões especiais. Aplique em pulsos e pescoço depois do banho. Desodorante colônia em frasco de 75ml.'),
    ('Caixa de Sabonetes em Barra Puro Vegetal Tododia (5 un. de 90g)', 'Caixa com 5 sabonetes em barra Puro Vegetal da linha Tododia, de 90g cada. Limpam a pele com suavidade e deixam um perfume agradável no banho. Ótima relação de custo e rendimento, ideal para a família toda e para manter sempre um estoque em casa.'),
    ('Caixa de Sabonetes em Barra Tododia Macadâmia (5 un. de 90g)', 'Caixa com 5 sabonetes em barra Tododia Macadâmia, de 90g cada. Limpam suavemente, deixam um toque macio na pele e um cheiro agradável em cada banho. Rendem bastante e são ótimos para toda a família manter um estoque em casa.'),
    ('Água de Colônia Mamãe e Bebê 100ml', 'Água de colônia suave e delicada da linha Mamãe e Bebê, com perfume leve que transmite carinho e aconchego. Uma fragrância gostosa para a mamãe e o bebê, ótima para usar depois do banho. Evite o contato com os olhos e siga as orientações da embalagem. Frasco de 100ml.'),
    ('Sabonete em Barra Mamãe e Bebê (Caixa c/ 5 un.)', 'Caixa com 5 sabonetes em barra Mamãe e Bebê, de limpeza suave e perfume delicado. Pensados para o banho de toda a família, cuidam da pele com carinho e transformam a hora do banho em um momento gostoso. Bom rendimento e ótima para manter em estoque.'),
    ('Shampoo Suave Mamãe e Bebê 200ml', 'Shampoo suave da linha Mamãe e Bebê, que limpa os fios com delicadeza e deixa os cabelos macios e cheirosos. Ideal para o uso frequente e para os cabelos mais finos dos pequenos. Evite o contato com os olhos. Frasco de 200ml.'),
    ('Creme para Pentear Mamãe e Bebê Cachos 200ml', 'Creme para pentear da linha Mamãe e Bebê, desenvolvido para cabelos cacheados. Ajuda a desembaraçar, facilita na hora de pentear e deixa os cachos macios, definidos e perfumados. Ótimo para tornar a rotina de cuidados mais tranquila. Frasco de 200ml.'),
    ('Polpa Hidratante para Mãos Ekos Castanha 75g', 'Polpa hidratante para as mãos da linha Ekos, com castanha. Textura rica e nutritiva que hidrata e deixa as mãos macias e cuidadas, com perfume agradável. Ótima para quem lava muito as mãos ou sofre com ressecamento. Bisnaga prática de 75g, perfeita para a bolsa.'),
    ('Óleo Desodorante Corporal Sève Amêndoas Doces 200ml', 'Óleo corporal desodorante com a fragrância de amêndoas doces da linha Sève. Aplique depois do banho, sobre a pele ainda úmida, para hidratar, deixar a pele macia com brilho acetinado e perfumada por mais tempo. Frasco de 200ml.'),
    ('Deo Parfum Essencial Exclusivo Masculino 100ml', 'Deo Parfum masculino da linha Essencial Exclusivo, com mais concentração e presença que uma colônia comum. Fragrância sofisticada e marcante, para o homem que valoriza elegância. Ótima para eventos, trabalho e para presentear. Frasco de 100ml.'),
    ('Desodorante Antitranspirante Roll-On Tododia Sem Perfume 70ml', 'Desodorante antitranspirante roll-on sem perfume da linha Tododia. Oferece proteção contra o suor e o odor, sem adicionar fragrância, ideal para quem prefere neutralidade ou usa perfume por cima. Aplicação prática e confortável no dia a dia. Frasco de 70ml.'),
    ('Shampoo Siàge Acelera o Crescimento 250ml', 'Shampoo da linha Siàge Acelera o Crescimento, formulado para fortalecer os fios desde a raiz e cuidar de cabelos que precisam de mais vitalidade. Limpa com eficiência e prepara o cabelo para o condicionador. Use com regularidade, de preferência em conjunto com a linha. Frasco de 250ml.'),
    ('Condicionador Siàge Acelera o Crescimento 200ml', 'Condicionador da linha Siàge Acelera o Crescimento, que ajuda a fortalecer os fios e deixa o cabelo macio, desembaraçado e com aparência saudável. Use depois do shampoo da linha para potencializar o cuidado. Frasco de 200ml.'),
    ('Leave-in Capilar Siàge Nutri Óleos Poderosos 100ml', 'Leave-in da linha Siàge Nutri Óleos Poderosos, com nutrição para cabelos ressecados. Aplique nos fios úmidos, sem enxaguar, para desembaraçar, proteger, dar brilho e deixar os fios macios e mais fáceis de pentear. Frasco de 100ml.'),
    ('Desodorante Body Spray La Victorie Intense 100ml', 'Body Spray feminino La Victorie Intense, com fragrância marcante e sedutora. Prático, de aplicação rápida, ótimo para renovar o perfume ao longo do dia. Frasco de 100ml, perfeito para a bolsa e para quem não abre mão de cheirar bem.'),
    ('Body Splash Desodorante Colônia Eudora 200ml', 'Body Splash da Eudora, perfume leve e refrescante para usar no corpo depois do banho ou ao longo do dia. Ótimo para dias quentes, fácil de reaplicar, com perfume agradável e feminino. Frasco grande de 200ml, que rende bastante.'),
    ('Body Splash Desodorante Colônia Instance Ameixa e Praliné 200ml', 'Body Splash da linha Instance, com a combinação gostosa e envolvente de ameixa e praliné. Um perfume doce e aconchegante, ótimo para o dia a dia. Borrife no corpo depois do banho e reaplique quando quiser. Combina com a loção hidratante da mesma linha. Frasco de 200ml.'),
    ('Loção Hidratante Desodorante Corporal Instance Ameixa e Praliné 400ml', 'Loção hidratante desodorante corporal da linha Instance, com a fragrância gostosa de ameixa e praliné. Textura leve que hidrata, deixa a pele macia e perfumada e é ótima para o uso diário depois do banho. Frasco grande de 400ml, que rende bastante.'),
    ('Protetor Solar Avon Care Sun+ Kids FPS 50 120g', 'Protetor solar infantil Avon Care Sun+ Kids com FPS 50, para a pele delicada das crianças. Aplique generosamente antes da exposição ao sol e reaplique ao menos a cada 2 horas, ou depois de suar ou entrar na água. Não substitui outras medidas de proteção solar. Bisnaga de 120g.'),
    ('Creme Redutor de Cutículas Mira-Cuticle Complexo com AHA 20g', 'Creme redutor de cutículas Mira-Cuticle com complexo de AHA, que ajuda a amaciar as cutículas e facilita a remoção na hora da manicure, deixando as unhas prontas para o esmalte. Siga o modo de uso da embalagem e evite o contato com a pele machucada. Bisnaga de 20g.'),
    ('Esmalte Color Trend Efeito Crystal - Rosa Crystal', 'Esmalte Color Trend Efeito Crystal na cor Rosa Crystal, com acabamento cristalino e brilho intenso. Cobre bem, tem aplicação fácil e deixa as unhas lindas e cheias de charme. Perfeito para compor looks delicados.'),
    ('Esmalte Color Trend Efeito Crystal - Preto Crystal', 'Esmalte Color Trend Efeito Crystal na cor Preto Crystal, com acabamento cristalino e brilho intenso. Uma cor sofisticada e marcante, ótima para quem quer unhas com muita personalidade. Aplicação fácil e boa cobertura.'),
    ('Esmalte Color Trend Efeito Crystal - Vermelho Crystal', 'Esmalte Color Trend Efeito Crystal na cor Vermelho Crystal, com acabamento cristalino e brilho intenso. Um vermelho clássico e poderoso, que dá destaque e sofisticação às unhas. Aplicação fácil e boa cobertura.'),
    ('Esmalte Color Trend Efeito Crystal - Prata Crystal', 'Esmalte Color Trend Efeito Crystal na cor Prata Crystal, com acabamento cristalino e brilho intenso. Uma cor moderna, versátil e cheia de brilho, perfeita para unhas diferentes e para criar produções criativas. Aplicação fácil e boa cobertura.')
) AS d(nome, descricao)
WHERE p.nome = d.nome AND (p.descricao IS NULL OR p.descricao = '');
